//! Read-only classroom availability over the existing INFO/WebVPN session.
//!
//! The public reference behavior used here is limited to the classroom
//! directory and weekly state pages.  This module deliberately owns the
//! legacy HTML boundary: request construction, GB2312 query encoding, route
//! validation, session-expiry classification, and the 42-slot parser stay in
//! Rust.  The adapter accepts a caller-owned [`CampusHttpTransport`] so an
//! INFO/WebVPN handoff and both classroom requests use the same Cookie jar.
//!
//! No WebVPN mapping, ticket, Cookie, or HTML document is exposed in the
//! returned records or error messages.  The module is standalone until the
//! runtime/service catalog integration is reviewed separately.

use std::{
    fmt,
    sync::atomic::{AtomicU64, Ordering},
    time::Duration,
};

use reqwest::{
    Method, StatusCode, Url,
    header::{ACCEPT, CONTENT_TYPE, LOCATION},
};
use serde::Serialize;
use thiserror::Error;

use crate::transport::{CampusHttpTransport, TransportError};

/// The default INFO roaming selector observed for both classroom operations.
/// It is a profile input, not an opaque URL and not a credential.
pub const CLASSROOM_ROAM_SELECTOR: &str = "40470BB47E0849E9EF717983490BC964";

pub const CLASSROOM_LIST_PATH: &str = "/portal3rd.do";
pub const CLASSROOM_LIST_QUERY: &str = "url=/portal3rd.do&m=jasJy_Xs_Js_index";
pub const CLASSROOM_STATE_PATH: &str = "/pk.classroomctrl.do";
pub const CLASSROOM_STATE_METHOD: &str = "qyClassroomState";
pub const CLASSROOM_STATE_QUERY_PREFIX: &str = "m=qyClassroomState&classroom=";
pub const CLASSROOM_STATE_QUERY_MIDDLE: &str = "&weeknumber=";
pub const CLASSROOM_STATUS_SLOT_COUNT: usize = 42;

const CLASSROOM_TIMEOUT_MESSAGE: &str = "time out用户登陆超时或访问内容不存在。请重试";
const CLASSROOM_WEBVPN_TITLE: &str = "清华大学WebVPN";
const MAX_HTML_BYTES: usize = 4 * 1024 * 1024;
const MAX_BUILDING_NAME_CHARS: usize = 256;

static NEXT_ADAPTER_BINDING: AtomicU64 = AtomicU64::new(1);

/// This slice only uses GET.  Keeping the method in the request plan makes a
/// future write route impossible to smuggle into this read-only adapter.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ClassroomHttpMethod {
    Get,
}

impl ClassroomHttpMethod {
    pub const fn as_reqwest(self) -> Method {
        match self {
            Self::Get => Method::GET,
        }
    }
}

/// A request requires an already established INFO/WebVPN Cookie session.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ClassroomSessionPrerequisite {
    ExistingInfoWebVpnSession,
}

/// One exact wire request.  `query` is already serialized because the state
/// route requires GB2312 bytes rather than UTF-8 query encoding.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ClassroomRequestPlan {
    pub operation: ClassroomOperation,
    pub method: ClassroomHttpMethod,
    pub path: String,
    pub query: String,
    pub body: Option<String>,
    pub session_prerequisite: ClassroomSessionPrerequisite,
}

impl ClassroomRequestPlan {
    pub fn query_string(&self) -> &str {
        &self.query
    }

    pub fn is_relative_path(&self) -> bool {
        self.path.starts_with('/') && !self.path.contains("://") && !self.path.contains(['?', '#'])
    }
}

/// The two observed classroom operations.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ClassroomOperation {
    BuildingList,
    WeeklyState,
}

/// Fixed classroom route profile.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct ClassroomReadProfile;

impl ClassroomReadProfile {
    pub const fn new() -> Self {
        Self
    }

    pub const fn roaming_selector(self) -> &'static str {
        CLASSROOM_ROAM_SELECTOR
    }

    pub fn building_list_request(self) -> ClassroomRequestPlan {
        ClassroomRequestPlan {
            operation: ClassroomOperation::BuildingList,
            method: ClassroomHttpMethod::Get,
            path: CLASSROOM_LIST_PATH.to_owned(),
            query: CLASSROOM_LIST_QUERY.to_owned(),
            body: None,
            session_prerequisite: ClassroomSessionPrerequisite::ExistingInfoWebVpnSession,
        }
    }

    pub fn weekly_state_request(
        self,
        building: &str,
        week: u32,
    ) -> Result<ClassroomRequestPlan, ClassroomRequestError> {
        let query = state_query(building, week)?;
        Ok(ClassroomRequestPlan {
            operation: ClassroomOperation::WeeklyState,
            method: ClassroomHttpMethod::Get,
            path: CLASSROOM_STATE_PATH.to_owned(),
            query,
            body: None,
            session_prerequisite: ClassroomSessionPrerequisite::ExistingInfoWebVpnSession,
        })
    }
}

/// Request construction errors.  No request is sent when one of these is
/// returned.
#[derive(Debug, Clone, PartialEq, Eq, Error)]
pub enum ClassroomRequestError {
    #[error("classroom WebVPN base URL is invalid")]
    InvalidBaseUrl,

    #[error("classroom name is empty")]
    EmptyBuilding,

    #[error("classroom name contains a control character")]
    ControlCharacter,

    #[error("classroom name is too long")]
    BuildingTooLong,

    #[error("week number must be greater than zero")]
    InvalidWeek,

    #[error("classroom character cannot be encoded as GB2312")]
    UnsupportedCharacter,
}

/// A building returned by the directory page.  `search_name` is the exact
/// server-side value recovered from the link and is the value used for the
/// state request; it is not a guessed transformation of the display name.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct ClassroomBuilding {
    pub name: String,
    pub search_name: String,
    pub week_number: u32,
}

/// A proof that a directory page was fetched and parsed successfully through
/// this adapter.  The binding is private and never serialized or printed.  A
/// weekly state call must use the proof from the same adapter, which keeps
/// the operation on the same caller-owned Cookie transport.
#[derive(Clone, PartialEq, Eq)]
pub struct ClassroomSessionProof {
    adapter_binding: u64,
}

/// The directory proof is a classroom business proof, not a copy of the
/// INFO session state.  Keep the historical `ClassroomSessionProof` name for
/// callers that already use `session_proof`, while exposing the business
/// meaning explicitly at this boundary.
pub type ClassroomBusinessProof = ClassroomSessionProof;

impl fmt::Debug for ClassroomSessionProof {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("ClassroomSessionProof")
    }
}

/// Directory result plus the session proof needed for the state request.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct ClassroomBuildingList {
    pub buildings: Vec<ClassroomBuilding>,
    #[serde(skip)]
    proof: ClassroomSessionProof,
}

impl ClassroomBuildingList {
    pub(crate) fn with_proof(buildings: Vec<ClassroomBuilding>, adapter_binding: u64) -> Self {
        Self {
            buildings,
            proof: ClassroomSessionProof { adapter_binding },
        }
    }

    /// Returns the proof handle bound to the adapter that produced this result.
    /// The handle carries no Cookie, ticket, URL, or user data.
    pub fn session_proof(&self) -> &ClassroomSessionProof {
        &self.proof
    }

    /// Returns the proof that the classroom directory was fetched and
    /// validated by this classroom adapter.
    pub fn business_proof(&self) -> &ClassroomBusinessProof {
        &self.proof
    }
}

/// A status for one of the 42 weekly slots.
///
/// The legacy page uses `onteaching`, `onexam`, `onborrowed`, and
/// `ondisabled`; a slot without a class after removing `colBound` is free.
/// Any other class is retained as [`Self::Unknown`] so a server-side status
/// addition cannot be silently reported as free.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub enum ClassroomSlotStatus {
    Free,
    Occupied,
    Exam,
    Borrowed,
    Disabled,
    Unknown { class_name: String },
}

/// One classroom and its exactly 42 Monday-first weekly slots.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct ClassroomState {
    pub name: String,
    pub status: Vec<ClassroomSlotStatus>,
}

/// Parsed weekly availability page.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct ClassroomStateResult {
    pub valid_week_numbers: Vec<u32>,
    pub current_week_number: u32,
    pub dates_of_current_week: [String; 7],
    pub classroom_states: Vec<ClassroomState>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ClassroomBusinessFailure {
    UpstreamTimeoutOrMissingPage,
}

#[derive(Debug, Clone, PartialEq, Eq, Error)]
pub enum ClassroomParseError {
    #[error("classroom response is an HTML login page")]
    LoginHtml,

    #[error("classroom response reports an upstream timeout or missing page")]
    TimeoutPage,

    #[error("classroom response is an unrecognized HTML page")]
    UnexpectedHtml,

    #[error("classroom response body is empty")]
    EmptyBody,

    #[error("building directory contains no validated classroom links")]
    EmptyBuildingList,

    #[error("building directory link has an unexpected path")]
    BuildingLinkPath,

    #[error("building directory link has an invalid query")]
    BuildingLinkQuery,

    #[error("building directory link has invalid percent encoding")]
    BuildingLinkEncoding,

    #[error("building directory link has an invalid week number")]
    BuildingLinkWeek,

    #[error("building directory link has an empty name")]
    BuildingLinkName,

    #[error("HTML structure is malformed")]
    MalformedHtml,

    #[error("weekly page has no valid week options")]
    MissingWeekOptions,

    #[error("weekly page contains an invalid week option")]
    InvalidWeekOption,

    #[error("requested week is not present in the weekly page options")]
    RequestedWeekUnavailable,

    #[error("weekly page has fewer than seven date headers")]
    MissingDateHeaders,

    #[error("weekly page has a malformed date header")]
    MalformedDateHeader,

    #[error("weekly page has no classroom table container")]
    MissingScrollContent,

    #[error("weekly page has no table body under the classroom container")]
    MissingClassroomTable,

    #[error("classroom row has an invalid column layout")]
    InvalidRowLayout,

    #[error("classroom row has an empty name")]
    EmptyClassroomName,
}

/// Errors raised while executing or parsing one classroom read.
#[derive(Debug, Error)]
pub enum ClassroomAdapterError {
    #[error("classroom WebVPN base URL is invalid")]
    InvalidBaseUrl,

    #[error("classroom request is invalid: {0}")]
    Request(#[from] ClassroomRequestError),

    #[error("classroom transport failed")]
    Transport(#[source] TransportError),

    #[error("classroom HTTP request returned {status}")]
    HttpStatus { status: StatusCode },

    #[error("classroom response came from an unexpected origin")]
    UnexpectedOrigin,

    #[error("classroom response ended outside the requested route")]
    UnexpectedPath,

    #[error("classroom INFO/WebVPN session has expired or is not established")]
    SessionExpired,

    #[error("classroom service reported a business failure: {kind:?}")]
    BusinessFailure { kind: ClassroomBusinessFailure },

    #[error("classroom response is not the expected HTML deployment")]
    UnexpectedDeployment,

    #[error("classroom session proof is required")]
    MissingSessionProof,

    #[error("classroom session proof belongs to another transport")]
    SessionProofMismatch,

    #[error("classroom building index is out of range")]
    InvalidBuildingIndex,

    #[error("classroom response could not be parsed: {0}")]
    Parse(#[source] ClassroomParseError),
}

impl ClassroomAdapterError {
    pub(crate) fn diagnostic_code(&self) -> &'static str {
        match self {
            Self::SessionExpired => "classroom_auth_required",
            Self::HttpStatus { .. } => "classroom_http",
            Self::UnexpectedOrigin => "classroom_origin",
            Self::UnexpectedPath => "classroom_response_path",
            Self::Transport(_) => "classroom_network",
            Self::UnexpectedDeployment => "classroom_deployment",
            Self::BusinessFailure { .. } => "classroom_business_rejected",
            Self::Parse(ClassroomParseError::MalformedHtml) => "classroom_html",
            Self::Parse(ClassroomParseError::EmptyBody) => "classroom_body_empty",
            Self::Parse(ClassroomParseError::EmptyBuildingList) => "classroom_buildings_empty",
            Self::Parse(ClassroomParseError::BuildingLinkPath) => "classroom_link_path",
            Self::Parse(ClassroomParseError::BuildingLinkQuery) => "classroom_link_query",
            Self::Parse(ClassroomParseError::BuildingLinkEncoding) => "classroom_link_encoding",
            Self::Parse(ClassroomParseError::BuildingLinkWeek) => "classroom_link_week",
            Self::Parse(_) => "classroom_parse",
            _ => "classroom_protocol",
        }
    }
    pub fn is_session_expired(&self) -> bool {
        matches!(self, Self::SessionExpired)
            || matches!(self, Self::Parse(ClassroomParseError::LoginHtml))
    }

    pub fn is_temporary_network(&self) -> bool {
        match self {
            Self::HttpStatus { status } => {
                *status == StatusCode::REQUEST_TIMEOUT
                    || *status == StatusCode::TOO_MANY_REQUESTS
                    || status.is_server_error()
            }
            Self::Transport(TransportError::Request(error)) => {
                error.is_timeout() || error.is_connect()
            }
            Self::Transport(TransportError::Decode(_)) => true,
            _ => false,
        }
    }
}

/// Configuration for the adapter.  It never creates a second transport or
/// performs an identity login.
#[derive(Clone)]
pub struct ClassroomAdapterConfig {
    base_url: Url,
    user_agent: String,
    timeout: Duration,
}

impl ClassroomAdapterConfig {
    pub fn new(base_url: &str) -> Result<Self, ClassroomAdapterError> {
        Self::with_user_agent_and_timeout(base_url, "THYou/classroom", Duration::from_secs(20))
    }

    pub fn with_user_agent_and_timeout(
        base_url: &str,
        user_agent: impl Into<String>,
        timeout: Duration,
    ) -> Result<Self, ClassroomAdapterError> {
        let base_url = Url::parse(base_url).map_err(|_| ClassroomAdapterError::InvalidBaseUrl)?;
        let base_url = normalize_base_url(base_url)?;
        let user_agent = user_agent.into();
        if user_agent.trim().is_empty() || user_agent.chars().any(char::is_control) {
            return Err(ClassroomAdapterError::InvalidBaseUrl);
        }
        Ok(Self {
            base_url,
            user_agent,
            timeout,
        })
    }

    pub fn base_url(&self) -> &Url {
        &self.base_url
    }

    pub fn try_build_transport(&self) -> Result<CampusHttpTransport, ClassroomAdapterError> {
        CampusHttpTransport::with_timeout(&self.user_agent, self.timeout)
            .map_err(|error| ClassroomAdapterError::Transport(TransportError::from(error)))
    }
}

/// Read-only classroom adapter.  The transport is caller-owned so it shares
/// the INFO/WebVPN Cookie jar.
pub struct ClassroomReadAdapter {
    base_url: Url,
    transport: CampusHttpTransport,
    profile: ClassroomReadProfile,
    binding: u64,
}

impl ClassroomReadAdapter {
    pub fn try_with_transport(
        base_url: Url,
        transport: CampusHttpTransport,
    ) -> Result<Self, ClassroomAdapterError> {
        let base_url = normalize_base_url(base_url)?;
        Ok(Self {
            base_url,
            transport,
            profile: ClassroomReadProfile::new(),
            binding: NEXT_ADAPTER_BINDING.fetch_add(1, Ordering::Relaxed),
        })
    }

    pub fn transport(&self) -> &CampusHttpTransport {
        &self.transport
    }

    pub fn profile(&self) -> ClassroomReadProfile {
        self.profile
    }

    pub async fn read_buildings(&self) -> Result<ClassroomBuildingList, ClassroomAdapterError> {
        let plan = self.profile.building_list_request();
        let body = self.execute(&plan).await?;
        let buildings = parse_building_list(&body).map_err(Self::map_parse_error)?;
        Ok(ClassroomBuildingList::with_proof(buildings, self.binding))
    }

    pub async fn read_state(
        &self,
        proof: &ClassroomSessionProof,
        building: &ClassroomBuilding,
        week: u32,
    ) -> Result<ClassroomStateResult, ClassroomAdapterError> {
        if !self.business_proof_matches(proof) {
            return Err(ClassroomAdapterError::SessionProofMismatch);
        }
        if building.search_name.trim().is_empty() {
            return Err(ClassroomAdapterError::Request(
                ClassroomRequestError::EmptyBuilding,
            ));
        }
        let plan = self
            .profile
            .weekly_state_request(&building.search_name, week)?;
        let body = self.execute(&plan).await?;
        parse_weekly_state(&body, week).map_err(Self::map_parse_error)
    }

    pub async fn read_state_from_list(
        &self,
        list: &ClassroomBuildingList,
        index: usize,
        week: u32,
    ) -> Result<ClassroomStateResult, ClassroomAdapterError> {
        if index >= list.buildings.len() {
            return Err(ClassroomAdapterError::InvalidBuildingIndex);
        }
        self.read_state(list.session_proof(), &list.buildings[index], week)
            .await
    }

    /// Returns whether a proof was created by this adapter's validated
    /// classroom directory request.  This is the business proof required by
    /// the weekly state operation; INFO authentication alone is insufficient.
    pub fn business_proof_matches(&self, proof: &ClassroomBusinessProof) -> bool {
        proof.adapter_binding == self.binding
    }

    async fn execute(&self, plan: &ClassroomRequestPlan) -> Result<String, ClassroomAdapterError> {
        if !plan.is_relative_path() {
            return Err(ClassroomAdapterError::InvalidBaseUrl);
        }
        let endpoint = endpoint_for_plan(&self.base_url, plan)?;
        let expected_path = endpoint.path().to_owned();
        let expected_query = plan.query.as_str();
        let response = self
            .transport
            .send(
                self.transport
                    .client()
                    .request(plan.method.as_reqwest(), endpoint.clone())
                    .header(ACCEPT, "text/html,application/xhtml+xml"),
            )
            .await
            .map_err(|error| ClassroomAdapterError::Transport(TransportError::Request(error)))?;
        let status = response.status();
        let final_url = response.url().clone();
        let content_type = response
            .headers()
            .get(CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .map(str::to_ascii_lowercase);
        let location = response
            .headers()
            .get(LOCATION)
            .map(|value| value.to_str().map(str::to_owned))
            .transpose()
            .map_err(|_| ClassroomAdapterError::UnexpectedOrigin)?;
        let location_target = location
            .as_deref()
            .map(|value| resolve_location(&final_url, value))
            .transpose()?;
        // An expired WebVPN mapping first lands on the same-origin `/login`
        // endpoint. That endpoint then points at the external OAuth service.
        // The shared transport intentionally stops before following that
        // cross-origin hop, so classify the same-origin login URL before
        // applying the origin policy below.
        if status == StatusCode::UNAUTHORIZED
            || status == StatusCode::FORBIDDEN
            || is_login_path(final_url.path())
            || location_target.as_ref().is_some_and(|target| {
                same_origin(&self.base_url, target) && is_login_path(target.path())
            })
        {
            return Err(ClassroomAdapterError::SessionExpired);
        }
        if location_target
            .as_ref()
            .is_some_and(|target| !same_origin(&self.base_url, target))
            || !same_origin(&self.base_url, &final_url)
        {
            return Err(ClassroomAdapterError::UnexpectedOrigin);
        }
        let body = crate::telemetry::timing::read_text(response)
            .await
            .map_err(|error| ClassroomAdapterError::Transport(TransportError::Decode(error)))?;

        if body.len() > MAX_HTML_BYTES {
            return Err(ClassroomAdapterError::UnexpectedDeployment);
        }
        match classify_page(&body) {
            Some(PageSignal::Login) => return Err(ClassroomAdapterError::SessionExpired),
            Some(PageSignal::Timeout) => {
                return Err(ClassroomAdapterError::BusinessFailure {
                    kind: ClassroomBusinessFailure::UpstreamTimeoutOrMissingPage,
                });
            }
            None => {}
        }
        if status != StatusCode::OK {
            return Err(ClassroomAdapterError::HttpStatus { status });
        }
        if final_url.path() != expected_path || final_url.query() != Some(expected_query) {
            return Err(ClassroomAdapterError::UnexpectedPath);
        }
        if let Some(content_type) = content_type
            && !content_type.contains("text/html")
            && !content_type.contains("application/xhtml+xml")
        {
            return Err(ClassroomAdapterError::UnexpectedDeployment);
        }
        Ok(body)
    }

    fn map_parse_error(error: ClassroomParseError) -> ClassroomAdapterError {
        match error {
            ClassroomParseError::LoginHtml => ClassroomAdapterError::SessionExpired,
            ClassroomParseError::TimeoutPage => ClassroomAdapterError::BusinessFailure {
                kind: ClassroomBusinessFailure::UpstreamTimeoutOrMissingPage,
            },
            other => ClassroomAdapterError::Parse(other),
        }
    }
}

impl fmt::Debug for ClassroomReadAdapter {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ClassroomReadAdapter")
            .field("scheme", &self.base_url.scheme())
            .field("host", &self.base_url.host_str())
            .field("has_opaque_path", &(!self.base_url.path().is_empty()))
            .field("profile", &self.profile)
            .finish()
    }
}

fn state_query(building: &str, week: u32) -> Result<String, ClassroomRequestError> {
    let building = building.trim();
    if building.is_empty() {
        return Err(ClassroomRequestError::EmptyBuilding);
    }
    if building.chars().any(char::is_control) {
        return Err(ClassroomRequestError::ControlCharacter);
    }
    if building.chars().count() > MAX_BUILDING_NAME_CHARS {
        return Err(ClassroomRequestError::BuildingTooLong);
    }
    if week == 0 {
        return Err(ClassroomRequestError::InvalidWeek);
    }
    Ok(format!(
        "{CLASSROOM_STATE_QUERY_PREFIX}{}{CLASSROOM_STATE_QUERY_MIDDLE}{week}",
        gb2312_percent_encode(building)?
    ))
}

/// Encodes a Unicode classroom value as percent-escaped GB2312 bytes.  ASCII
/// unreserved bytes remain literal; every other byte is encoded as `%XX`.
pub fn gb2312_percent_encode(value: &str) -> Result<String, ClassroomRequestError> {
    let bytes = encode_gb2312(value)?;
    let mut encoded = String::with_capacity(bytes.len() * 3);
    for byte in bytes {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'.' | b'_' | b'~') {
            encoded.push(char::from(byte));
        } else {
            encoded.push('%');
            encoded.push(hex_digit(byte >> 4));
            encoded.push(hex_digit(byte & 0x0f));
        }
    }
    Ok(encoded)
}

fn hex_digit(value: u8) -> char {
    match value {
        0..=9 => char::from(b'0' + value),
        10..=15 => char::from(b'A' + value - 10),
        _ => unreachable!(),
    }
}

fn encode_gb2312(value: &str) -> Result<Vec<u8>, ClassroomRequestError> {
    let mut output = Vec::with_capacity(value.len());
    for character in value.chars() {
        if character.is_ascii() {
            output.push(character as u8);
            continue;
        }
        let Some(index) = GB2312_TABLE
            .binary_search_by_key(&character, |(unicode, _)| *unicode)
            .ok()
        else {
            return Err(ClassroomRequestError::UnsupportedCharacter);
        };
        let encoded = GB2312_TABLE[index].1;
        output.push((encoded >> 8) as u8);
        output.push(encoded as u8);
    }
    Ok(output)
}

fn decode_query_component(value: &str) -> Result<String, ClassroomParseError> {
    let mut bytes = Vec::with_capacity(value.len());
    let value = value.replace('+', " ");
    let characters: Vec<char> = value.chars().collect();
    let mut index = 0;
    while index < characters.len() {
        if characters[index] == '%' {
            if index + 2 >= characters.len() {
                return Err(ClassroomParseError::BuildingLinkEncoding);
            }
            let high = hex_value(characters[index + 1])
                .ok_or(ClassroomParseError::BuildingLinkEncoding)?;
            let low = hex_value(characters[index + 2])
                .ok_or(ClassroomParseError::BuildingLinkEncoding)?;
            bytes.push((high << 4) | low);
            index += 3;
        } else {
            let mut buffer = [0; 4];
            let encoded = characters[index].encode_utf8(&mut buffer);
            bytes.extend_from_slice(encoded.as_bytes());
            index += 1;
        }
    }
    if bytes.iter().all(|byte| *byte < 0x80) {
        return String::from_utf8(bytes).map_err(|_| ClassroomParseError::BuildingLinkEncoding);
    }
    if let Ok(value) = String::from_utf8(bytes.clone()) {
        return Ok(value);
    }
    decode_gb2312(&bytes).ok_or(ClassroomParseError::BuildingLinkEncoding)
}

fn decode_gb2312(bytes: &[u8]) -> Option<String> {
    let mut output = String::with_capacity(bytes.len());
    let mut index = 0;
    while index < bytes.len() {
        let first = bytes[index];
        if first < 0x80 {
            output.push(char::from(first));
            index += 1;
            continue;
        }
        let second = *bytes.get(index + 1)?;
        let code = u16::from(first) << 8 | u16::from(second);
        let character = GB2312_TABLE
            .iter()
            .find_map(|(unicode, encoded)| (*encoded == code).then_some(*unicode))?;
        output.push(character);
        index += 2;
    }
    Some(output)
}

fn hex_value(value: char) -> Option<u8> {
    match value {
        '0'..='9' => Some(value as u8 - b'0'),
        'a'..='f' => Some(value as u8 - b'a' + 10),
        'A'..='F' => Some(value as u8 - b'A' + 10),
        _ => None,
    }
}

fn validate_base_url(url: &Url) -> Result<(), ClassroomAdapterError> {
    if !matches!(url.scheme(), "http" | "https")
        || url.host_str().is_none()
        || !url.username().is_empty()
        || url.password().is_some()
        || url.query().is_some()
        || url.fragment().is_some()
        || url.path().contains(['\\', '?', '#'])
        || url.path().contains("..")
        || url.path().chars().any(char::is_control)
        || invalid_percent_encoding(url.path())
        || path_contains_encoded_escape(url.path())
    {
        return Err(ClassroomAdapterError::InvalidBaseUrl);
    }
    Ok(())
}

fn normalize_base_url(mut url: Url) -> Result<Url, ClassroomAdapterError> {
    if url.query().is_some() {
        let is_classroom_entry = url
            .path()
            .trim_end_matches('/')
            .ends_with(CLASSROOM_LIST_PATH)
            && query_matches_literal(url.query().unwrap_or_default(), CLASSROOM_LIST_QUERY);
        if !is_classroom_entry {
            return Err(ClassroomAdapterError::InvalidBaseUrl);
        }
        url.set_query(None);
    }

    validate_base_url(&url)?;
    let mut path = url.path().trim_end_matches('/').to_owned();
    if path.ends_with(CLASSROOM_LIST_PATH) {
        path.truncate(path.len() - CLASSROOM_LIST_PATH.len());
        if path.is_empty() {
            path.push('/');
        }
    }
    if let Some(mapping_root) = opaque_mapping_root(&path) {
        path = mapping_root;
    }
    let normalized = if path.is_empty() || path == "/" {
        "/".to_owned()
    } else {
        format!("{path}/")
    };
    url.set_path(&normalized);
    Ok(url)
}

fn query_matches_literal(actual: &str, expected: &str) -> bool {
    let mut actual = actual
        .split('&')
        .map(|pair| pair.split_once('='))
        .collect::<Option<Vec<_>>>();
    let mut expected = expected
        .split('&')
        .map(|pair| pair.split_once('='))
        .collect::<Option<Vec<_>>>();
    let (Some(actual), Some(expected)) = (actual.as_mut(), expected.as_mut()) else {
        return false;
    };
    actual.sort_unstable();
    expected.sort_unstable();
    actual.as_slice() == expected.as_slice()
}

fn opaque_mapping_root(path: &str) -> Option<String> {
    let mut segments = path.split('/').filter(|segment| !segment.is_empty());
    let scheme = segments.next()?;
    if !matches!(scheme, "http" | "https") {
        return None;
    }
    let token = segments.next()?;
    Some(format!("/{scheme}/{token}/"))
}

fn path_contains_encoded_escape(path: &str) -> bool {
    let bytes = path.as_bytes();
    bytes.windows(3).any(|window| {
        window[0] == b'%'
            && hex_value(char::from(window[1]))
                .zip(hex_value(char::from(window[2])))
                .is_some_and(|(high, low)| {
                    matches!((high << 4) | low, b'.' | b'/' | b'\\' | 0x00..=0x1f | 0x7f)
                })
    })
}

fn endpoint_for_plan(
    base_url: &Url,
    plan: &ClassroomRequestPlan,
) -> Result<Url, ClassroomAdapterError> {
    let mut endpoint = base_url.clone();
    let base_path = endpoint.path().trim_end_matches('/');
    endpoint.set_path(&format!("{base_path}{}", plan.path));
    endpoint.set_query(Some(&plan.query));
    endpoint.set_fragment(None);
    Ok(endpoint)
}

fn invalid_percent_encoding(value: &str) -> bool {
    let bytes = value.as_bytes();
    let mut index = 0;
    while index < bytes.len() {
        if bytes[index] == b'%' {
            if index + 2 >= bytes.len()
                || hex_value(char::from(bytes[index + 1])).is_none()
                || hex_value(char::from(bytes[index + 2])).is_none()
            {
                return true;
            }
            index += 3;
        } else {
            index += 1;
        }
    }
    false
}

fn same_origin(left: &Url, right: &Url) -> bool {
    left.scheme() == right.scheme()
        && left.host_str() == right.host_str()
        && left.port_or_known_default() == right.port_or_known_default()
        && right.username().is_empty()
        && right.password().is_none()
}

fn is_login_path(path: &str) -> bool {
    let lower = path.to_ascii_lowercase();
    lower
        .split('/')
        .any(|segment| matches!(segment, "login" | "auth" | "authserver"))
        || lower.contains("/do/off/ui/auth/login")
        || lower.contains("/auth/login")
        || lower.contains("/sso/login")
}

fn resolve_location(response_url: &Url, location: &str) -> Result<Url, ClassroomAdapterError> {
    if location.chars().any(char::is_control) || invalid_percent_encoding(location) {
        return Err(ClassroomAdapterError::UnexpectedOrigin);
    }
    let target = Url::parse(location)
        .or_else(|_| response_url.join(location))
        .map_err(|_| ClassroomAdapterError::UnexpectedOrigin)?;
    if target.fragment().is_some() {
        return Err(ClassroomAdapterError::UnexpectedOrigin);
    }
    Ok(target)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PageSignal {
    Login,
    Timeout,
}

fn classify_page(body: &str) -> Option<PageSignal> {
    let normalized = body
        .chars()
        .filter(|character| !character.is_whitespace())
        .collect::<String>();
    let lower = normalized.to_ascii_lowercase();
    if body.contains(CLASSROOM_TIMEOUT_MESSAGE)
        || lower.contains("timeout用户登陆超时或访问内容不存在")
    {
        return Some(PageSignal::Timeout);
    }
    if normalized.contains(CLASSROOM_WEBVPN_TITLE)
        || lower.contains("清华大学webvpn")
        || lower.contains("name=\"i_user\"")
        || lower.contains("name='i_user'")
        || lower.contains("name=i_user")
        || lower.contains("name=\"i_pass\"")
        || lower.contains("name='i_pass'")
        || lower.contains("name=i_pass")
        || lower.contains("id=\"net_default_loginctrl1_txtusername\"")
        || lower.contains("id='net_default_loginctrl1_txtusername'")
        || lower.contains("id=net_default_loginctrl1_txtusername")
        || lower.contains("id=\"net_default_loginctrl1_txtuserpwd\"")
        || lower.contains("id='net_default_loginctrl1_txtuserpwd'")
        || lower.contains("id=net_default_loginctrl1_txtuserpwd")
        || (lower.contains("type=\"password\"") && lower.contains("<form"))
        || (lower.contains("type='password'") && lower.contains("<form"))
        || (lower.contains("type=password") && lower.contains("<form"))
        || lower.contains("j_acegi_formlogin")
    {
        return Some(PageSignal::Login);
    }
    None
}

fn parse_building_list(html: &str) -> Result<Vec<ClassroomBuilding>, ClassroomParseError> {
    if html.trim().is_empty() {
        return Err(ClassroomParseError::EmptyBody);
    }
    match classify_page(html) {
        Some(PageSignal::Login) => return Err(ClassroomParseError::LoginHtml),
        Some(PageSignal::Timeout) => return Err(ClassroomParseError::TimeoutPage),
        None => {}
    }
    let document = parse_html_document(html)?;
    let mut buildings = Vec::new();
    collect_building_links(&document, false, &mut buildings)?;
    if buildings.is_empty() {
        return Err(ClassroomParseError::EmptyBuildingList);
    }
    Ok(buildings)
}

fn collect_building_links(
    node: &HtmlNode,
    inside_w30: bool,
    output: &mut Vec<ClassroomBuilding>,
) -> Result<(), ClassroomParseError> {
    let Some(tag) = node.tag.as_deref() else {
        for child in &node.children {
            collect_building_links(child, inside_w30, output)?;
        }
        return Ok(());
    };
    let has_w30 = inside_w30 || has_class(node, "w30");
    if tag == "a" && inside_w30 {
        if let Some(href) = attr(node, "href") {
            if href.starts_with("/http/") {
                // The reference ignores sidebar/help links without a building
                // and week selector. A real candidate still fails strictly on
                // invalid path, duplicate selector, bad encoding or zero week.
                if let Some((_, query)) = href.split_once('?') {
                    let fields: Vec<_> = query
                        .split('&')
                        .filter_map(|pair| pair.split_once('=').map(|(name, _)| name))
                        .collect();
                    if fields.contains(&"classroom") && fields.contains(&"weeknumber") {
                        output.push(parse_building_link(href, text_content(node))?);
                    }
                }
            }
        }
    }
    for child in &node.children {
        collect_building_links(child, has_w30, output)?;
    }
    Ok(())
}

fn parse_building_link(
    href: &str,
    display_name: String,
) -> Result<ClassroomBuilding, ClassroomParseError> {
    if !href.starts_with("/http/") || href.contains(['#', '\\']) {
        return Err(ClassroomParseError::BuildingLinkPath);
    }
    let (path, query) = href
        .split_once('?')
        .ok_or(ClassroomParseError::BuildingLinkQuery)?;
    if !path.ends_with(CLASSROOM_STATE_PATH) {
        return Err(ClassroomParseError::BuildingLinkPath);
    }
    let mut method = None;
    let mut classroom = None;
    let mut week = None;
    for pair in query.split('&') {
        let (key, value) = pair
            .split_once('=')
            .ok_or(ClassroomParseError::BuildingLinkQuery)?;
        let key = decode_query_component(key)?;
        match key.as_str() {
            "m" if method.is_none() => method = Some(decode_query_component(value)?),
            "classroom" if classroom.is_none() => classroom = Some(decode_query_component(value)?),
            "weeknumber" if week.is_none() => week = Some(decode_query_component(value)?),
            "m" | "classroom" | "weeknumber" => return Err(ClassroomParseError::BuildingLinkQuery),
            _ => {}
        }
    }
    if method.as_deref() != Some(CLASSROOM_STATE_METHOD) {
        return Err(ClassroomParseError::BuildingLinkQuery);
    }
    let search_name = classroom.ok_or(ClassroomParseError::BuildingLinkQuery)?;
    if search_name.trim().is_empty() {
        return Err(ClassroomParseError::BuildingLinkName);
    }
    let week_number = week
        .as_deref()
        .and_then(|value| value.parse::<u32>().ok())
        .filter(|value| *value > 0)
        .ok_or(ClassroomParseError::BuildingLinkWeek)?;
    let name = decode_text(&display_name);
    if name.trim().is_empty() || name.chars().count() > MAX_BUILDING_NAME_CHARS {
        return Err(ClassroomParseError::BuildingLinkName);
    }
    Ok(ClassroomBuilding {
        name,
        search_name,
        week_number,
    })
}

fn parse_weekly_state(
    html: &str,
    requested_week: u32,
) -> Result<ClassroomStateResult, ClassroomParseError> {
    if html.trim().is_empty() {
        return Err(ClassroomParseError::EmptyBody);
    }
    match classify_page(html) {
        Some(PageSignal::Login) => return Err(ClassroomParseError::LoginHtml),
        Some(PageSignal::Timeout) => return Err(ClassroomParseError::TimeoutPage),
        None => {}
    }
    let document = parse_html_document(html)?;
    let week_selects = elements_with_id(&document, "weeknumber");
    if week_selects.len() != 1 {
        return Err(ClassroomParseError::MissingWeekOptions);
    }
    let mut valid_week_numbers = Vec::new();
    for option in descendants_by_tag(week_selects[0], "option") {
        let value = attr(option, "value").ok_or(ClassroomParseError::InvalidWeekOption)?;
        let value = value
            .parse::<u32>()
            .ok()
            .filter(|value| *value > 0)
            .ok_or(ClassroomParseError::InvalidWeekOption)?;
        if valid_week_numbers.contains(&value) {
            return Err(ClassroomParseError::InvalidWeekOption);
        }
        valid_week_numbers.push(value);
    }
    if valid_week_numbers.is_empty() {
        return Err(ClassroomParseError::MissingWeekOptions);
    }
    if !valid_week_numbers.contains(&requested_week) {
        return Err(ClassroomParseError::RequestedWeekUnavailable);
    }

    let date_headers = elements_with_attr(&document, "colspan", "6");
    if date_headers.len() < 7 {
        return Err(ClassroomParseError::MissingDateHeaders);
    }
    let mut dates = Vec::with_capacity(7);
    for header in date_headers.into_iter().take(7) {
        let text = text_content(header);
        let Some(open) = text.find('(') else {
            return Err(ClassroomParseError::MalformedDateHeader);
        };
        let Some(close) = text[open + 1..].find(')') else {
            return Err(ClassroomParseError::MalformedDateHeader);
        };
        let date = text[open + 1..open + 1 + close].trim();
        if date.is_empty() {
            return Err(ClassroomParseError::MalformedDateHeader);
        }
        dates.push(date.to_owned());
    }
    let dates_of_current_week: [String; 7] = dates
        .try_into()
        .map_err(|_| ClassroomParseError::MissingDateHeaders)?;

    let scroll_contents = elements_with_id(&document, "scrollContent");
    if scroll_contents.len() != 1 {
        return Err(ClassroomParseError::MissingScrollContent);
    }
    let tables = direct_children_by_tag(scroll_contents[0], "table");
    if tables.is_empty() {
        return Err(ClassroomParseError::MissingClassroomTable);
    }
    let mut classroom_states = Vec::new();
    let mut body_count = 0;
    for table in tables {
        for tbody in direct_children_by_tag(table, "tbody") {
            body_count += 1;
            for row in direct_children_by_tag(tbody, "tr") {
                classroom_states.push(parse_classroom_row(row)?);
            }
        }
    }
    if body_count == 0 {
        return Err(ClassroomParseError::MissingClassroomTable);
    }
    Ok(ClassroomStateResult {
        valid_week_numbers,
        current_week_number: requested_week,
        dates_of_current_week,
        classroom_states,
    })
}

fn parse_classroom_row(row: &HtmlNode) -> Result<ClassroomState, ClassroomParseError> {
    let cells = element_children(row);
    if cells.iter().any(|cell| cell.tag.as_deref() != Some("td")) {
        return Err(ClassroomParseError::InvalidRowLayout);
    }
    // Reference Cheerio indexes raw child nodes, including newlines:
    // children[1] is the FIRST cell; slice(3) skips that cell and two text
    // nodes, not three metadata columns. Retain the explicit legacy layout.
    let (name_index, slots_start) = match cells.len() {
        n if n == 1 + CLASSROOM_STATUS_SLOT_COUNT => (0, 1),
        n if n == 3 + CLASSROOM_STATUS_SLOT_COUNT => (1, 3),
        _ => return Err(ClassroomParseError::InvalidRowLayout),
    };
    if cells[slots_start..].iter().any(|cell| {
        ["rowspan", "colspan"]
            .iter()
            .any(|key| attr(cell, key).is_some_and(|value| value.trim() != "1"))
    }) {
        return Err(ClassroomParseError::InvalidRowLayout);
    }
    let name = text_content(cells[name_index]);
    if name.trim().is_empty() {
        return Err(ClassroomParseError::EmptyClassroomName);
    }
    let status = cells[slots_start..]
        .iter()
        .map(|cell| parse_slot_status(cell))
        .collect();
    Ok(ClassroomState {
        name: name.trim().to_owned(),
        status,
    })
}

fn parse_slot_status(cell: &HtmlNode) -> ClassroomSlotStatus {
    let class_name = attr(cell, "class").unwrap_or_default();
    let classes: Vec<&str> = class_name
        .split_whitespace()
        .filter(|class| *class != "colBound")
        .collect();
    match classes.as_slice() {
        [] => ClassroomSlotStatus::Free,
        ["onteaching"] => ClassroomSlotStatus::Occupied,
        ["onexam"] => ClassroomSlotStatus::Exam,
        ["onborrowed"] => ClassroomSlotStatus::Borrowed,
        ["ondisabled"] => ClassroomSlotStatus::Disabled,
        _ => ClassroomSlotStatus::Unknown {
            class_name: classes.join(" "),
        },
    }
}

#[derive(Debug, Clone)]
struct HtmlNode {
    tag: Option<String>,
    attrs: Vec<(String, String)>,
    text: Option<String>,
    children: Vec<HtmlNode>,
}

impl HtmlNode {
    fn document(children: Vec<HtmlNode>) -> Self {
        Self {
            tag: None,
            attrs: Vec::new(),
            text: None,
            children,
        }
    }

    fn element(tag: String, attrs: Vec<(String, String)>) -> Self {
        Self {
            tag: Some(tag),
            attrs,
            text: None,
            children: Vec::new(),
        }
    }

    fn text(text: String) -> Self {
        Self {
            tag: None,
            attrs: Vec::new(),
            text: Some(text),
            children: Vec::new(),
        }
    }
}

fn parse_html_document(html: &str) -> Result<HtmlNode, ClassroomParseError> {
    if html.len() > MAX_HTML_BYTES {
        return Err(ClassroomParseError::MalformedHtml);
    }
    // Like reference Cheerio, recover standard HTML5 optional end tags.
    // Business validity is decided by the real selectors/records, not XML
    // well-formedness. The parser never executes scripts or accesses URLs.
    fn convert(
        element: scraper::ElementRef<'_>,
        depth: usize,
        count: &mut usize,
    ) -> Result<HtmlNode, ClassroomParseError> {
        *count += 1;
        if depth > 128 || *count > 100_000 {
            return Err(ClassroomParseError::MalformedHtml);
        }
        let name = element.value().name().to_owned();
        let attrs = element
            .value()
            .attrs()
            .map(|(name, value)| (name.to_owned(), value.to_owned()))
            .collect();
        let mut result = HtmlNode::element(name.clone(), attrs);
        if matches!(name.as_str(), "script" | "style") {
            return Ok(result);
        }
        for child in element.children() {
            if let Some(child) = scraper::ElementRef::wrap(child) {
                result.children.push(convert(child, depth + 1, count)?);
            } else if let Some(text) = child.value().as_text() {
                result.children.push(HtmlNode::text(text.to_string()));
            }
        }
        Ok(result)
    }
    let document = scraper::Html::parse_document(html);
    Ok(HtmlNode::document(vec![convert(
        document.root_element(),
        0,
        &mut 0,
    )?]))
}

fn find_tag_end(value: &str) -> Option<usize> {
    let mut quote = None;
    for (index, character) in value.char_indices() {
        match (quote, character) {
            (None, '\'' | '"') => quote = Some(character),
            (Some(current), character) if current == character => quote = None,
            (None, '>') => return Some(index),
            _ => {}
        }
    }
    None
}

fn find_raw_text_close(html: &str, start: usize, tag: &str) -> Option<(usize, usize)> {
    if start >= html.len() {
        return None;
    }
    let lower = html.to_ascii_lowercase();
    let needle = format!("</{tag}");
    let mut cursor = start;
    while let Some(relative) = lower[cursor..].find(&needle) {
        let close_start = cursor + relative;
        let after_name = close_start + needle.len();
        let boundary = lower.as_bytes().get(after_name).copied();
        if boundary.is_some_and(|byte| byte.is_ascii_whitespace() || byte == b'>') {
            let close_end = find_tag_end(&html[close_start + 1..])? + close_start + 1;
            return Some((close_start, close_end));
        }
        cursor = after_name;
    }
    None
}

fn parse_start_tag(
    raw: &str,
) -> Result<(String, Vec<(String, String)>, bool), ClassroomParseError> {
    let mut value = raw.trim();
    let self_closing = value.ends_with('/');
    if self_closing {
        value = value[..value.len() - 1].trim_end();
    }
    let name_end = value.find(char::is_whitespace).unwrap_or(value.len());
    if name_end == 0 {
        return Err(ClassroomParseError::MalformedHtml);
    }
    let tag = value[..name_end].to_ascii_lowercase();
    let mut attrs = Vec::new();
    let mut cursor = name_end;
    while cursor < value.len() {
        while cursor < value.len() && value.as_bytes()[cursor].is_ascii_whitespace() {
            cursor += 1;
        }
        if cursor == value.len() {
            break;
        }
        let name_start = cursor;
        while cursor < value.len()
            && !value.as_bytes()[cursor].is_ascii_whitespace()
            && value.as_bytes()[cursor] != b'='
        {
            cursor += 1;
        }
        if name_start == cursor {
            return Err(ClassroomParseError::MalformedHtml);
        }
        let name = value[name_start..cursor].to_ascii_lowercase();
        if attrs.iter().any(|(current, _)| current == &name) {
            return Err(ClassroomParseError::MalformedHtml);
        }
        while cursor < value.len() && value.as_bytes()[cursor].is_ascii_whitespace() {
            cursor += 1;
        }
        let mut attr_value = String::new();
        if cursor < value.len() && value.as_bytes()[cursor] == b'=' {
            cursor += 1;
            while cursor < value.len() && value.as_bytes()[cursor].is_ascii_whitespace() {
                cursor += 1;
            }
            if cursor == value.len() {
                return Err(ClassroomParseError::MalformedHtml);
            }
            let quote = matches!(value.as_bytes()[cursor], b'\'' | b'"')
                .then(|| value.as_bytes()[cursor] as char);
            if let Some(quote) = quote {
                cursor += 1;
                let start = cursor;
                while cursor < value.len() && value.as_bytes()[cursor] as char != quote {
                    cursor += 1;
                }
                if cursor == value.len() {
                    return Err(ClassroomParseError::MalformedHtml);
                }
                attr_value = decode_text(&value[start..cursor]);
                cursor += 1;
            } else {
                let start = cursor;
                while cursor < value.len() && !value.as_bytes()[cursor].is_ascii_whitespace() {
                    cursor += 1;
                }
                attr_value = decode_text(&value[start..cursor]);
            }
        }
        attrs.push((name, attr_value));
    }
    Ok((tag, attrs, self_closing))
}

fn append_node(stack: &mut Vec<HtmlNode>, roots: &mut Vec<HtmlNode>, node: HtmlNode) {
    if let Some(parent) = stack.last_mut() {
        parent.children.push(node);
    } else {
        roots.push(node);
    }
}

fn attr<'a>(node: &'a HtmlNode, name: &str) -> Option<&'a str> {
    node.attrs
        .iter()
        .find(|(key, _)| key == name)
        .map(|(_, value)| value.as_str())
}

fn has_class(node: &HtmlNode, class: &str) -> bool {
    attr(node, "class").is_some_and(|value| value.split_whitespace().any(|item| item == class))
}

fn element_children(node: &HtmlNode) -> Vec<&HtmlNode> {
    node.children
        .iter()
        .filter(|child| child.tag.is_some())
        .collect()
}

fn direct_children_by_tag<'a>(node: &'a HtmlNode, tag: &str) -> Vec<&'a HtmlNode> {
    node.children
        .iter()
        .filter(|child| child.tag.as_deref() == Some(tag))
        .collect()
}

fn descendants_by_tag<'a>(node: &'a HtmlNode, tag: &str) -> Vec<&'a HtmlNode> {
    let mut output = Vec::new();
    collect_descendants_by_tag(node, tag, &mut output);
    output
}

fn collect_descendants_by_tag<'a>(node: &'a HtmlNode, tag: &str, output: &mut Vec<&'a HtmlNode>) {
    if node.tag.as_deref() == Some(tag) {
        output.push(node);
    }
    for child in &node.children {
        collect_descendants_by_tag(child, tag, output);
    }
}

fn elements_with_id<'a>(node: &'a HtmlNode, id: &str) -> Vec<&'a HtmlNode> {
    let mut output = Vec::new();
    collect_elements_with_id(node, id, &mut output);
    output
}

fn collect_elements_with_id<'a>(node: &'a HtmlNode, id: &str, output: &mut Vec<&'a HtmlNode>) {
    if node.tag.is_some() && attr(node, "id") == Some(id) {
        output.push(node);
    }
    for child in &node.children {
        collect_elements_with_id(child, id, output);
    }
}

fn elements_with_attr<'a>(node: &'a HtmlNode, name: &str, value: &str) -> Vec<&'a HtmlNode> {
    let mut output = Vec::new();
    collect_elements_with_attr(node, name, value, &mut output);
    output
}

fn collect_elements_with_attr<'a>(
    node: &'a HtmlNode,
    name: &str,
    value: &str,
    output: &mut Vec<&'a HtmlNode>,
) {
    if node.tag.is_some() && attr(node, name).is_some_and(|current| current.trim() == value) {
        output.push(node);
    }
    for child in &node.children {
        collect_elements_with_attr(child, name, value, output);
    }
}

fn text_content(node: &HtmlNode) -> String {
    let mut output = String::new();
    collect_text(node, &mut output);
    output
}

fn collect_text(node: &HtmlNode, output: &mut String) {
    if let Some(text) = &node.text {
        output.push_str(text);
    }
    for child in &node.children {
        collect_text(child, output);
    }
}

fn decode_text(value: &str) -> String {
    let mut output = String::with_capacity(value.len());
    let mut cursor = 0;
    while let Some(relative_start) = value[cursor..].find('&') {
        let start = cursor + relative_start;
        output.push_str(&value[cursor..start]);
        let Some(relative_end) = value[start..].find(';') else {
            output.push('&');
            cursor = start + 1;
            continue;
        };
        let end = start + relative_end;
        let entity = &value[start + 1..end];
        let decoded = match entity {
            "amp" => Some('&'),
            "lt" => Some('<'),
            "gt" => Some('>'),
            "quot" => Some('"'),
            "apos" | "#39" => Some('\''),
            _ if entity.starts_with("#x") || entity.starts_with("#X") => {
                u32::from_str_radix(&entity[2..], 16)
                    .ok()
                    .and_then(char::from_u32)
            }
            _ if entity.starts_with('#') => entity[1..].parse().ok().and_then(char::from_u32),
            _ => None,
        };
        if let Some(decoded) = decoded {
            output.push(decoded);
            cursor = end + 1;
        } else {
            output.push_str(&value[start..=end]);
            cursor = end + 1;
        }
    }
    output.push_str(&value[cursor..]);
    output
}

